SELECT jsonb_build_object('events',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT id_evento,nome_evento,tag,ativo,cidade,estado,data_inicial,data_final,id_agrega_evento,url_inscricao,url_hotsite,url_regulamento,categorias,endereco,descricao,md5(to_jsonb(e)::text) row_hash FROM tb_evento_corridas e WHERE tag IN ('2026-maratona-de-curitiba-santander-2026','2026-maratona-monumental-de-brasilia-2026','2026-live-run-xp-brasilia-2026-iii','2026-santander-night-run-etapa-1-curitiba-2026','2026-night-run-etapa-1-curitiba-2026','2027-maratona-internacional-de-floripa-fibra-2027') OR (id_agrega_evento IN (SELECT id_agrega_evento FROM tb_agrega_eventos WHERE tag IN ('maratona-de-curitiba','maratona-monumental-de-brasilia')) AND ativo)) x),'families',(SELECT jsonb_agg(to_jsonb(a)) FROM tb_agrega_eventos a WHERE tag IN ('maratona-de-curitiba','maratona-monumental-de-brasilia','maratona-internacional-de-floripa','live-run-xp','circuito-das-estacoes')),'circuits',(SELECT jsonb_agg(to_jsonb(g)) FROM tb_agregadores g WHERE agregador_tipo='circuito' AND (agregador_tag ILIKE '%live%' OR agregador_tag ILIKE '%estacoes%')),'triggers',(SELECT jsonb_agg(pg_get_triggerdef(oid)) FROM pg_trigger WHERE tgrelid IN ('tb_evento_corridas'::regclass,'tb_evento_corridas_percursos'::regclass) AND NOT tgisinternal),'auditTables',(SELECT jsonb_agg(table_name) FROM information_schema.tables WHERE table_schema='public' AND (table_name ILIKE '%fact%' OR table_name ILIKE '%seo%')))::text payload
